mapper.update:
update staff_account
set first_login = false, updated_at = current_timestamp
where id = #{staffId} and tenant_id = #{tenantId}

mapper.select:
select count(*)
from bookable_slot
where id = #{slotId} and tenant_id = #{tenantId} and staff_account_id = #{staffId}

select id as "attendanceId", booking_id as "bookingId", confirmed_at as "confirmedAt"
from attendance_confirm
where booking_id = #{bookingId} and tenant_id = #{tenantId}

insert into attendance_confirm(
  tenant_id, store_id, booking_id, member_id, member_card_id, confirmed_by_staff_id
) values (
  #{tenantId}, #{storeId}, #{bookingId}, #{memberId}, #{memberCardId}, #{staffId}
)
returning id

mapper.update:
update booking
set status = 'arrived', updated_at = current_timestamp
where id = #{bookingId} and tenant_id = #{tenantId}

update member_card
set remain_count = remain_count - #{deductCount}, updated_at = current_timestamp
where id = #{memberCardId}
  and tenant_id = #{tenantId}
  and remain_count >= #{deductCount}

mapper.select:
insert into deduction_record(
  tenant_id, store_id, booking_id, attendance_id, member_id, member_card_id,
  deduct_count, before_count, after_count, deducted_by_staff_id
) values (
  #{tenantId}, #{storeId}, #{bookingId}, #{attendanceId}, #{memberId}, #{memberCardId},
  #{deductCount}, #{beforeCount}, #{afterCount}, #{staffId}
)
returning id

mapper.update:
update booking
set status = 'deducted', updated_at = current_timestamp
where id = #{bookingId} and tenant_id = #{tenantId}

mapper.insert:
insert into service_note(
  tenant_id, booking_id, deduction_record_id, staff_note_text, member_feedback_text
) values (
  #{tenantId}, #{bookingId}, #{deductionId}, #{staffNote}, #{memberFeedback}
)
on conflict (booking_id) do update
set staff_note_text = excluded.staff_note_text,
  member_feedback_text = excluded.member_feedback_text,
  updated_at = current_timestamp

mapper.update:
update booking
set status = 'note_done', updated_at = current_timestamp
where id = #{bookingId} and tenant_id = #{tenantId}
